function h($v){return Util::e($v);} function csrf(){return Csrf::input();} function t(string $v):string{return I18n::t($v);}
function routePath(): string { $p=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/'; return rtrim($p,'/')?:'/'; }
function method():string{return strtoupper($_SERVER['REQUEST_METHOD']??'GET');}
function validProjectUrl(string $url):bool{
    if(!filter_var($url,FILTER_VALIDATE_URL))return false;$u=parse_url($url);if(!$u)return false;
    $scheme=strtolower((string)($u['scheme']??''));$host=strtolower(rtrim((string)($u['host']??''),'.'));
    if(!in_array($scheme,['http','https'],true)||$host===''||isset($u['user'])||isset($u['pass']))return false;
    if(isset($u['port'])&&!in_array((int)$u['port'],[80,443],true))return false;
    if($host==='localhost'||str_ends_with($host,'.localhost')||str_ends_with($host,'.local'))return false;
    $ipHost=trim($host,'[]');if($ipHost!==$host&&!filter_var($ipHost,FILTER_VALIDATE_IP))return false;
    if(filter_var($ipHost,FILTER_VALIDATE_IP)&&!filter_var($ipHost,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return false;
    return true;
}
function normalizeProjectUrl(string $url):string{$u=parse_url($url);if(!$u)return $url;$scheme=strtolower((string)$u['scheme']);$host=strtolower(rtrim((string)$u['host'],'.'));$port=isset($u['port'])?':'.(int)$u['port']:'';$path=(string)($u['path']??'/');return $scheme.'://'.$host.$port.($path===''?'/':$path);}
function projectBySlug(string $slug,string $role='viewer'):array{$p=DB::one('SELECT * FROM projects WHERE slug=?',[$slug]);if(!$p||!Auth::canProject((int)$p['id'],$role)){http_response_code($role==='viewer'?404:403);exit($role==='viewer'?'Project not found':'Forbidden');}return $p;}
function audit(string $action,?int $pid=null,array $meta=[]):void{DB::exec('INSERT INTO audit_logs(user_id,project_id,action_key,ip_hash,meta_json) VALUES(?,?,?,?,?)',[Auth::id(),$pid,$action,Util::hashIp(Util::ip()),json_encode($meta)]);}
function isProjectOwner(int $pid):bool{$uid=Auth::id();if(!$uid)return false;$r=DB::one('SELECT role FROM project_members WHERE project_id=? AND user_id=?',[$pid,$uid]);return ($r['role']??'')==='owner';}
function ownerTestMode():bool{return Env::bool('OWNER_ACCEPTANCE_MODE',false)||(strtolower((string)Env::get('APP_ENV','production'))!=='production'&&Env::bool('OWNER_TEST_MODE',false));} function tokenCost(string $key,int $default,?int $pid=null):int{$base=max(0,(int)Env::get($key,$default));if($pid&&ownerTestMode()&&isProjectOwner($pid))return 0;return $base;}
function tokenCostLabel(string $key,int $default,int $pid):string{$cost=tokenCost($key,$default,$pid);return $cost===0?'Free in owner acceptance mode':number_format($cost).' tokens';}
function useTokens(int $amount,string $action,string $description,?int $pid=null):void{if($amount<=0)return;DB::tx(function()use($amount,$action,$description,$pid){$lock=((string)DB::pdo()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')?' FOR UPDATE':'';$u=DB::one('SELECT token_balance,bonus_tokens FROM users WHERE id=?'.$lock,[Auth::id()]);$total=(int)($u['token_balance']??0)+(int)($u['bonus_tokens']??0);if(!$u||$total<$amount)throw new RuntimeException('Not enough tokens.');if($pid){$proj=DB::one('SELECT monthly_token_cap FROM projects WHERE id=?',[$pid]);if($proj&&!empty($proj['monthly_token_cap'])){$start=date('Y-m-01 00:00:00');$net=(int)(DB::one('SELECT COALESCE(SUM(tokens_delta),0) v FROM usage_ledger WHERE user_id=? AND project_id=? AND created_at>=?',[Auth::id(),$pid,$start])['v']??0);$used=max(0,-$net);if($used+$amount>(int)$proj['monthly_token_cap'])throw new RuntimeException('This project reached its monthly token cap.');}}$bonusUse=min((int)$u['bonus_tokens'],$amount);$cycleUse=$amount-$bonusUse;DB::exec('UPDATE users SET bonus_tokens=bonus_tokens-?,token_balance=token_balance-? WHERE id=?',[$bonusUse,$cycleUse,Auth::id()]);DB::exec('INSERT INTO usage_ledger(user_id,project_id,action_key,description,tokens_delta) VALUES(?,?,?,?,?)',[Auth::id(),$pid,$action,$description,-$amount]);});}
function refundTokens(int $amount,string $action,string $description,?int $pid=null):void{if($amount<=0)return;DB::exec('UPDATE users SET bonus_tokens=bonus_tokens+? WHERE id=?',[$amount,Auth::id()]);DB::exec('INSERT INTO usage_ledger(user_id,project_id,action_key,description,tokens_delta) VALUES(?,?,?,?,?)',[Auth::id(),$pid,$action,$description,$amount]);}
function rewardReferralIfEligible():void{
    $uid=Auth::id();if(!$uid)return;$cycle=date('Y-m');
    DB::tx(function()use($uid,$cycle):void{
        $lock=((string)DB::pdo()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')?' FOR UPDATE':'';
        $ref=DB::one('SELECT * FROM referrals WHERE referred_user_id=? AND status="pending"'.$lock,[$uid]);if(!$ref)return;
        // Serialize rewards for the same referrer so concurrent first scans cannot
        // exceed the monthly referral cap or credit the same referral twice.
        DB::one('SELECT id FROM users WHERE id=?'.$lock,[$ref['referrer_user_id']]);
        $count=(int)(DB::one('SELECT COUNT(*) c FROM referrals WHERE referrer_user_id=? AND status="activated" AND reward_cycle_key=?',[$ref['referrer_user_id'],$cycle])['c']??0);if($count>=5)return;
        DB::exec('UPDATE referrals SET status="activated",activated_at=CURRENT_TIMESTAMP,reward_cycle_key=? WHERE id=? AND status="pending"',[$cycle,$ref['id']]);
        DB::exec('UPDATE users SET bonus_tokens=bonus_tokens+1000 WHERE id=?',[$ref['referrer_user_id']]);
        DB::exec('UPDATE users SET referral_rewarded_at=COALESCE(referral_rewarded_at,CURRENT_TIMESTAMP) WHERE id=?',[$uid]);
        DB::exec('INSERT INTO usage_ledger(user_id,project_id,action_key,description,tokens_delta) VALUES(?,NULL,"referral_reward","Referral completed first scan",1000)',[$ref['referrer_user_id']]);
        NotificationService::record((int)$ref['referrer_user_id'],null,'referral','Referral activated','A referred builder completed their first scan. 1,000 bonus tokens were added.','/account/referrals',true);
    });
}
function recordScanCompletion(string $action,int $projectId,array $meta=[],bool $rewardReferral=false):void{
    try{if($rewardReferral)rewardReferralIfEligible();audit($action,$projectId,$meta);}catch(Throwable $e){error_log('Scan completion side effect: '.$e->getMessage());}
}
