            return $created;
        });
        audit('project.created',$pid);unset($_SESSION['public_audit'],$_SESSION['public_url'],$_SESSION['public_answers'],$_SESSION['public_discovery'],$_SESSION['public_discovery_error']);Util::redirect('/builds/'.$slug.'/onboarding');
    }catch(Throwable $e){error_log('Import failed: '.$e->getMessage());$importError='Could not import this product. Check the URL and try again.';include __DIR__.'/../app/Views/app/import.php';}
